CREATE TEMP VIEW _s301_ge37_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1: The beloved son, the coat, the brethren who received him not
    ('canon','genesis',37,4,'canon','john',1,11,'free',
      E'*He came unto his own, and his own received him not* (John 1:11). The hatred of the brethren — *when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him* (Genesis 37:4) — is the type the Most High would fill in the Formed Son: the beloved one *came unto his own, and his own received him not*. Read as type, never as flattening: as the loved son of Jacob was hated and refused by his own brethren, so the Son the Father loved came to his own and was not received — the rejected-then-raised pattern set down at the head of the Joseph cycle.'),
    ('canon','genesis',37,3,'jasher','jasher',41,6,'extras',
      E'*And Jacob, his father, also loved him more than any of his sons, for he was a son of his old age, and through his love toward him, he made him a coat of many colors* (Jasher 41:6). The extended witness keeps the favour entire — *loved him more than any of his sons, for he was a son of his old age... a coat of many colors* — matching *Now Yashar''el (Israel) loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours* (Genesis 37:3). The coat marks the beloved son, the one set above his brethren.'),
    ('canon','genesis',37,4,'jasher','jasher',41,8,'extras',
      E'*And the sons of Jacob seeing the whole of Joseph''s conduct toward them, and that their father loved him more than any of them, they hated him and could not speak peaceably to him all the days* (Jasher 41:8). The extended witness carries the brethren''s hatred whole — *they hated him and could not speak peaceably to him* — the very words of *they hated him, and could not speak peaceably unto him* (Genesis 37:4): the beloved son refused by his own.'),

    -- THREAD 2 (★★): The dreams — the sheaves and the stars shall bow (exaltation foretold)
    ('canon','genesis',37,9,'canon','philippians',2,9,'free',
      E'*Wherefore Elohim (God) also hath highly exalted him, and given him a name which is above every name* (Philippians 2:9). The dream of *the sun and the moon and the eleven stars made obeisance to me* (Genesis 37:9) foretells exaltation of the one his brethren rejected. As type it presses forward: the One brought low — sold, afflicted — *Elohim also hath highly exalted him.* The bowing of the heavens in the dream is the homage owed to the rejected-then-raised Son.'),
    ('canon','genesis',37,9,'canon','philippians',2,10,'free',
      E'*That at the name of Yahusha (Jesus) every knee should bow, of things in heaven, and things in earth, and things under the earth* (Philippians 2:10). The sheaves that *made obeisance to my sheaf* (Genesis 37:7) and the sun, moon, and stars that *made obeisance to me* (Genesis 37:9) are the dream-shadow of *every knee should bow.* The one the brethren scorned — *Shalt thou indeed reign over us?* (Genesis 37:8) — is the one before whom heaven and earth shall bow; the dream of dominion is the type of the Name above every name.'),
    ('canon','genesis',37,7,'canon','genesis',42,6,'free',
      E'*And Joseph was the governor over the land, and he it was that sold to all the people of the land: and Joseph''s brethren came, and bowed down themselves before him with their faces to the earth* (Genesis 42:6). The first dream — *behold, your sheaves stood round about, and made obeisance to my sheaf* (Genesis 37:7) — is fulfilled within the cycle itself: the brethren who hated the dreamer come and *bowed down themselves before him with their faces to the earth.* The rejected brother, raised to rule, is bowed to by the very ones who sold him — the dream made good.'),
    ('canon','genesis',37,9,'canon','revelation',12,1,'free',
      E'*And there appeared a great wonder in heaven; a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars* (Revelation 12:1). The luminaries of Joseph''s dream — *the sun and the moon and the eleven stars made obeisance to me* (Genesis 37:9), which his father read as *I and thy mother and thy brethren* (Genesis 37:10) — return in the great sign: the woman clothed with the sun, the moon, the twelve stars — the household of Yashar''el (Israel) gathered under the same heavenly imagery, the family of the covenant out of whom the seed comes.'),
    ('canon','genesis',37,9,'jasher','jasher',41,14,'extras',
      E'*And after this Joseph dreamed another dream and related the dream to his father in the presence of his brethren, and Joseph said to his father and brethren, Behold I have again dreamed a dream, and behold the sun and the moon and the eleven stars bowed down to me* (Jasher 41:14). The extended witness keeps the second dream whole — *the sun and the moon and the eleven stars bowed down to me* — matching *the sun and the moon and the eleven stars made obeisance to me* (Genesis 37:9): the heavens themselves rehearsing the homage owed the exalted one.'),

    -- THREAD 3 (★★): Behold, this dreamer cometh — let us slay him
    ('canon','genesis',37,20,'canon','matthew',21,38,'free',
      E'*But when the husbandmen saw the son, they said among themselves, This is the heir; come, let us kill him, and let us seize on his inheritance* (Matthew 21:38). The conspiracy against the dreamer — *Behold, this dreamer cometh. Come now therefore, and let us slay him... and we shall see what will become of his dreams* (Genesis 37:19-20) — is the type Yahusha (Jesus) Himself draws in the parable: the heir sent to his own, and the murderous counsel *come, let us kill him.* As Joseph''s brethren plotted to void the dreams of dominion by his death, so the husbandmen plot to seize the inheritance by slaying the son.'),
    ('canon','genesis',37,20,'jasher','jasher',41,25,'extras',
      E'*And Simeon said to his brethren, Behold the man of dreams is coming to us this day, and now therefore come and let us kill him and cast him in one of the pits that are in the wilderness, and when his father shall seek him from us, we will say an evil beast has devoured him* (Jasher 41:25). The extended witness names the plot in full — *Behold the man of dreams is coming... let us kill him and cast him in one of the pits... an evil beast has devoured him* — the very shape of *Behold, this dreamer cometh... let us slay him, and cast him into some pit... Some evil beast hath devoured him* (Genesis 37:19-20).'),

    -- THREAD 4 (★★): Sold for twenty pieces of silver — the betrayal of the brother
    ('canon','genesis',37,28,'canon','matthew',26,15,'free',
      E'*And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver* (Matthew 26:15). Joseph sold by his brethren — *sold Joseph to the Ishmeelites for twenty pieces of silver* (Genesis 37:28), at Yahudah''s (Judah''s) counsel *let us sell him* (Genesis 37:27) — is the type pressed forward: the brother delivered up for silver, *they covenanted with him for thirty pieces of silver.* The one his own valued at a slave''s price and handed to strangers is the shadow of the One priced and betrayed; that Yahudah (Judah) the brother proposed the sale carries the lateral to the betrayal without collapsing the two.'),
    ('canon','genesis',37,28,'canon','zechariah',11,12,'free',
      E'*And I said unto them, If ye think good, give me my price; and if not, forbear. So they weighed for my price thirty pieces of silver* (Zechariah 11:12). The selling of Joseph for silver — *sold Joseph to the Ishmeelites for twenty pieces of silver* (Genesis 37:28) — opens the silver-for-the-shepherd type the prophet seals: *they weighed for my price thirty pieces of silver.* The shepherd priced and sold by those he came to is the line that runs from the pit at Dothan to the potter''s field.'),
    ('canon','genesis',37,28,'canon','zechariah',11,13,'free',
      E'*And Yahuah (LORD) said unto me, Cast it unto the potter: a goodly price that I was prised at of them. And I took the thirty pieces of silver, and cast them to the potter in the house of Yahuah (LORD)* (Zechariah 11:13). The price hung on the brother — *for twenty pieces of silver* (Genesis 37:28) — finds its prophetic measure in the *goodly price that I was prised at of them*, the silver cast to the potter. The selling of the beloved for money is named by Yahuah as the contemptible valuation of the One who shepherds His people.'),
    ('canon','genesis',37,28,'jasher','jasher',42,19,'extras',
      E'*And the sons of Jacob hearkened to the Midianites and they sold their brother Joseph to them for twenty pieces of silver, and Reuben their brother was not with them, and the Midianites took Joseph and continued their journey to Gilead* (Jasher 42:19). The extended witness keeps the sale entire — *they sold their brother Joseph to them for twenty pieces of silver* — matching *sold Joseph to the Ishmeelites for twenty pieces of silver* (Genesis 37:28): the brother handed over for a price, Reuben absent who would have saved him.'),
    ('canon','genesis',37,27,'jubilees','jubilees',34,11,'extras',
      E'*And they dealt treacherously with him, and formed a plot against him to slay him, but changing their minds, they sold him to Ishmaelite merchants, and they brought him down into Egypt, and they sold him to Potiphar, the eunuch of Pharaoh... And the sons of Jacob slaughtered a kid, and dipped the coat of Joseph in the blood, and sent (it) to Jacob their father* (Jubilees 34:11). The restored witness carries the counsel of *Come, and let us sell him to the Ishmeelites... for he is our brother and our flesh* (Genesis 37:27): the plot to slay turned to a sale, *they sold him to Ishmaelite merchants, and they brought him down into Egypt* — the brother sold rather than slain.'),

    -- THREAD 5: Stripped of the coat, cast into the pit, and down into sheol
    ('canon','genesis',37,23,'jasher','jasher',41,27,'extras',
      E'*And when Joseph came to his brethren he sat before them, and they rose upon him and seized him and smote him to the earth, and stripped the coat of many colors which he had on* (Jasher 41:27). The extended witness keeps the stripping whole — *they... stripped the coat of many colors which he had on* — matching *they stript Joseph out of his coat, his coat of many colours that was on him* (Genesis 37:23): the mark of the beloved son torn from him before the pit, the first stripping of the rejected one.'),
    ('canon','genesis',37,24,'jasher','jasher',41,28,'extras',
      E'*And they took him and cast him into a pit, and in the pit there was no water, but serpents and scorpions... And Joseph cried out with a loud voice, and Yahuah (the Lord) hid the serpents and scorpions in the sides of the pit, and they did no harm to Joseph* (Jasher 41:28). The extended witness opens the pit of *they took him, and cast him into a pit: and the pit was empty, there was no water in it* (Genesis 37:24): the waterless pit, the descent of the one presumed dead — and even there Yahuah preserves him, the kept one in the place of death.'),
    ('canon','genesis',37,35,'jubilees','jubilees',34,16,'extras',
      E'*And he mourned for Joseph one year, and did not cease, for he said "Let me go down to the grave mourning for my son."* (Jubilees 34:16). The restored witness keeps the father''s grief — *Let me go down to the grave mourning for my son* — matching *I will go down into the grave unto my son mourning* (Genesis 37:35): the father refuses comfort, the son reckoned among the dead and gone down to sheol, the deepest point of the descent before the raising.'),

    -- THREAD 6 (★★): The patriarchs, moved with envy, sold Joseph into Egypt — the load-bearing witness
    ('canon','genesis',37,28,'canon','acts',7,9,'free',
      E'*And the patriarchs, moved with envy, sold Joseph into Egypt: but Elohim (God) was with him* (Acts 7:9). The Spirit through Stephen reads the whole chapter in a breath: *the patriarchs, moved with envy* — the envy of *his brethren envied him* (Genesis 37:11) — *sold Joseph into Egypt* — the sale of *sold Joseph to the Ishmeelites... and they brought Joseph into Egypt* (Genesis 37:28) — *but Elohim (God) was with him.* This is the explicit NT naming of Joseph sold-by-envy as the type the Spirit preaches: rejected by his own, yet Yahuah with him through it.'),
    ('canon','genesis',37,28,'canon','acts',7,10,'free',
      E'*And delivered him out of all his afflictions, and gave him favour and wisdom in the sight of Pharaoh king of Egypt; and he made him governor over Egypt and all his house* (Acts 7:10). The sale into Egypt — *they brought Joseph into Egypt* (Genesis 37:28) — is read forward to its end: *delivered him out of all his afflictions... made him governor over Egypt.* The very pattern the dreams foretold and the pit denied is the type entire: the rejected, sold, afflicted one raised to rule and to save — the suffering-then-exalted shape the Joseph cycle sets down.'),
    ('canon','genesis',37,20,'canon','genesis',50,20,'free',
      E'*But as for you, ye thought evil against me; but Elohim (God) meant it unto good, to bring to pass, as it is this day, to save much people alive* (Genesis 50:20). The murderous counsel — *let us slay him, and cast him into some pit... and we shall see what will become of his dreams* (Genesis 37:20) — is answered by Joseph''s own naming of the whole arc: *ye thought evil against me; but Elohim (God) meant it unto good... to save much people alive.* The evil meant against the rejected brother is overruled to the saving of the many — the type of the One rejected and raised to deliver His people.'),

    -- THREAD 7: The stick of Joseph, the birthright, and the northern house (two-house weave)
    ('canon','genesis',37,3,'canon','ezekiel',37,16,'free',
      E'*Moreover, thou son of Adam, take thee one stick, and write upon it, For Yahudah (Judah), and for the children of Yashar''el (Israel) his companions: then take another stick, and write upon it, For Joseph, the stick of Ephraim, and for all the house of Yashar''el (Israel) his companions* (Ezekiel 37:16). The pre-eminence Jacob lays on the beloved son — *loved Joseph more than all his children... a coat of many colours* (Genesis 37:3) — is the favour that makes Joseph the head of the northern house: *another stick... For Joseph, the stick of Ephraim, and for all the house of Yashar''el (Israel).* The coat sets the brother above; the prophet names him the stick of the scattered house.'),
    ('canon','genesis',37,3,'canon','ezekiel',37,19,'free',
      E'*Say unto them, Thus saith Adonai Yahuah (the Lord GOD); Behold, I will take the stick of Joseph, which is in the hand of Ephraim... and will put them with him, even with the stick of Yahudah (Judah), and make them one stick, and they shall be one in mine hand* (Ezekiel 37:19). The brother set above all his children (Genesis 37:3) and then rejected by them becomes the stick of the gathering: *I will take the stick of Joseph... and make them one stick.* The rejected brother is the saved-and-saving northern house, joined again to Yahudah (Judah) — two sticks made one in Yahuah''s hand.'),
    ('canon','genesis',37,3,'canon','1-chronicles',5,1,'free',
      E'*Now the sons of Reuben the firstborn of Yashar''el (Israel), (for he was the firstborn; but, forasmuch as he defiled his father''s bed, his birthright was given unto the sons of Joseph the son of Yashar''el (Israel): and the genealogy is not to be reckoned after the birthright* (1 Chronicles 5:1). The favour shown the beloved son — *Yashar''el (Israel) loved Joseph more than all his children... and he made him a coat of many colours* (Genesis 37:3) — is named as the birthright itself: *his birthright was given unto the sons of Joseph.* The coat of many colours is the visible token of the firstborn''s portion passing to Joseph and his house.'),
    ('canon','genesis',37,3,'canon','1-chronicles',5,2,'free',
      E'*For Yahudah (Judah) prevailed above his brethren, and of him came the chief ruler; but the birthright was Joseph''s* (1 Chronicles 5:2). The two-house pattern is set already in the favour of Genesis 37:3: *the birthright was Joseph''s* (the northern house, Ephraim) even as *of him [Yahudah/Judah] came the chief ruler* (the southern house, the Davidic line). The beloved son carries the birthright; the brother Yahudah (Judah) who sold him carries the sceptre — the two houses whose sticks must be made one.'),
    ('canon','genesis',37,9,'canon','revelation',7,8,'free',
      E'*Of the tribe of Zabulon were sealed twelve thousand. Of the tribe of Joseph were sealed twelve thousand. Of the tribe of Benjamin were sealed twelve thousand* (Revelation 7:8). The eleven stars that bowed to Joseph (Genesis 37:9) and the household gathered under sun and moon become, at the last, the sealed tribes — *of the tribe of Joseph were sealed twelve thousand.* The rejected brother whose dreams his family scorned stands among the sealed of Yashar''el (Israel), the northern house gathered and numbered with his brethren.'),

    -- THREAD 8: The kid of the goats and the Day of Atonement
    ('canon','genesis',37,31,'jubilees','jubilees',34,18,'extras',
      E'*For this reason it is ordained for the children of Yashar''el (Israel) that they should afflict themselves on the tenth of the seventh month... that they should make atonement for themselves thereon with a young goat on the tenth of the seventh month, once a year, for their sins; for they had grieved the affection of their father regarding Joseph his son* (Jubilees 34:18). The restored witness binds the goat of *they took Joseph''s coat, and killed a kid of the goats, and dipped the coat in the blood* (Genesis 37:31) to the very origin of the Day of Atonement: the goat slain to cover the brothers'' deceit becomes the *young goat* of the tenth of the seventh month, the affliction of souls for sin.'),
    ('canon','genesis',37,31,'canon','leviticus',16,5,'free',
      E'*And he shall take of the congregation of the children of Yashar''el (Israel) two kids of the goats for a sin offering, and one ram for a burnt offering* (Leviticus 16:5). The kid of the goats killed to cover the brothers'' sin — *killed a kid of the goats, and dipped the coat in the blood* (Genesis 37:31) — anticipates the appointed goats of the Atonement rite: *two kids of the goats for a sin offering.* The goat whose blood deceived the father is the shadow of the goat whose blood would cover the people''s guilt.'),
    ('canon','genesis',37,31,'canon','leviticus',23,27,'free',
      E'*Also on the tenth day of this seventh month there shall be a day of atonement: it shall be an holy convocation unto you; and ye shall afflict your souls, and offer an offering made by fire unto Yahuah (LORD)* (Leviticus 23:27). The deceit sealed in goat''s blood — *killed a kid of the goats, and dipped the coat in the blood* (Genesis 37:31) — is bound by the restored reckoning to *a day of atonement... ye shall afflict your souls*: the brothers'' grievous wrong against the beloved son named as the very day Yashar''el (Israel) afflicts itself for sin.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s301_ge37_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s301_ge37_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-the-beloved-son-the-coat-and-the-brethren-who-received-him-not',
       E'The beloved son, the coat of many colours, and the brethren who received him not',
       E'The Joseph cycle opens on a father''s love and a brothers'' hatred: *Now Yashar''el (Israel) loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours* (Genesis 37:3). The coat is the token of the beloved son, the one set above his brethren — and it kindles the hatred: *when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him* (Genesis 37:4). This is the head of the great type. Read FORWARD to the Formed Son the Father loved: *He came unto his own, and his own received him not* (John 1:11). As the loved son of Jacob was hated and refused by his own brethren, so the Son the Father loved came to his own and was not received. Framed as type through the Formed-and-the-Formless: Joseph foreshadows the rejected-then-raised One — never a flattening of the Son into a patriarch, never co-equal-persons grammar; the shape (beloved-son-refused-by-his-own) is the type the cycle sets down. The extended witness keeps the favour and the hatred whole: *Jacob, his father, also loved him more than any of his sons, for he was a son of his old age... he made him a coat of many colors* (Jasher 41:6), and *they hated him and could not speak peaceably to him all the days* (Jasher 41:8). The beloved son, marked by the coat, refused by his own — and the whole arc of suffering-then-glory begins here.',
       sv.verse_id, ev.verse_id, 'extras', 20900
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=3
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-the-dreams-the-sheaves-and-the-stars-shall-bow',
       E'The dreams — the sheaves and the stars shall bow (exaltation foretold)',
       E'Twice the rejected dreamer is shown his exaltation. First the field: *behold, we were binding sheaves in the field, and, lo, my sheaf arose, and also stood upright; and, behold, your sheaves stood round about, and made obeisance to my sheaf* (Genesis 37:7) — and the brethren read it rightly and rage: *Shalt thou indeed reign over us? or shalt thou indeed have dominion over us? And they hated him yet the more* (Genesis 37:8). Then the heavens: *the sun and the moon and the eleven stars made obeisance to me* (Genesis 37:9), which his father reads as the whole household bowing (Genesis 37:10). The dreams of dominion given to the one his own would sell are the shadow of the exaltation of the rejected-then-raised One: *Wherefore Elohim (God) also hath highly exalted him, and given him a name which is above every name* (Philippians 2:9), *that at the name of Yahusha (Jesus) every knee should bow, of things in heaven, and things in earth, and things under the earth* (Philippians 2:10). And the first dream is fulfilled within the cycle: *Joseph''s brethren came, and bowed down themselves before him with their faces to the earth* (Genesis 42:6) — the sheaves bowing made good. The luminary imagery returns at the last sign: *a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars* (Revelation 12:1) — the household of Yashar''el (Israel) under sun, moon, and twelve. The extended witness keeps the second dream whole: *the sun and the moon and the eleven stars bowed down to me* (Jasher 41:14). The one scorned is the one to be bowed to.',
       sv.verse_id, ev.verse_id, 'extras', 20903
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=5
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=11
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-behold-this-dreamer-cometh-let-us-slay-him',
       E'Behold, this dreamer cometh — let us slay him (the conspiracy against the heir)',
       E'They see him while he is yet far off, and the hatred hardens into a plot: *when they saw him afar off, even before he came near unto them, they conspired against him to slay him. And they said one to another, Behold, this dreamer cometh* (Genesis 37:18-19). The counsel is to kill the dreamer and void his dreams: *Come now therefore, and let us slay him, and cast him into some pit, and we will say, Some evil beast hath devoured him: and we shall see what will become of his dreams* (Genesis 37:20). This is the type Yahusha (Jesus) Himself drew in the parable of the vineyard: *when the husbandmen saw the son, they said among themselves, This is the heir; come, let us kill him, and let us seize on his inheritance* (Matthew 21:38). As the brethren plot to murder the heir and so undo the dreams of his dominion, so the husbandmen plot to slay the son and seize the inheritance. The rejected one is plotted against by his own — the murderous counsel raised against the beloved. The extended witness names the plot in full: *Behold the man of dreams is coming to us this day... let us kill him and cast him in one of the pits that are in the wilderness, and when his father shall seek him from us, we will say an evil beast has devoured him* (Jasher 41:25). The dreams will not be undone by the killing; the very plot becomes the road to the throne.',
       sv.verse_id, ev.verse_id, 'extras', 20906
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=18
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=20
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-sold-for-twenty-pieces-of-silver-the-betrayal-of-the-brother',
       E'Sold for twenty pieces of silver — the betrayal of the brother',
       E'Reuben would have saved him — *Shed no blood... lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again* (Genesis 37:22) — but it is Yahudah (Judah) who turns the killing into a sale: *What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites... for he is our brother and our flesh* (Genesis 37:26-27). And so the deed: *they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt* (Genesis 37:28). The brother sold for silver is the type pressed forward — *What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver* (Matthew 26:15) — and named by the prophet: *they weighed for my price thirty pieces of silver* (Zechariah 11:12), *a goodly price that I was prised at of them... and cast them to the potter in the house of Yahuah (LORD)* (Zechariah 11:13). The one his own valued at a slave''s price and handed to strangers is the shadow of the One priced and betrayed; that Yahudah (Judah) proposed the sale carries the lateral to the betrayer without collapsing the two. The extended witnesses keep the sale entire: *they sold their brother Joseph to them for twenty pieces of silver* (Jasher 42:19); and the restored reckoning: *changing their minds, they sold him to Ishmaelite merchants, and they brought him down into Egypt* (Jubilees 34:11). The brother sold rather than slain — and carried down to the place of his rising.',
       sv.verse_id, ev.verse_id, 'extras', 20909
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=26
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=28
ON CONFLICT (slug) DO NOTHING;

-- THREAD 5
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-stripped-of-the-coat-cast-into-the-pit-and-down-into-sheol',
       E'Stripped of the coat, cast into the pit, and down into sheol (the descent)',
       E'Before the sale comes the stripping and the descent. First the coat — the token of the beloved son — is torn from him: *when Joseph was come unto his brethren, that they stript Joseph out of his coat, his coat of many colours that was on him* (Genesis 37:23). Then the pit: *they took him, and cast him into a pit: and the pit was empty, there was no water in it* (Genesis 37:24). Then the deceit of the blood-dipped coat, and the father given over to grief as for the dead: *I will go down into the grave unto my son mourning* (Genesis 37:35) — the father reckons his son among the dead, gone down to sheol. This is the descent of the rejected one, stripped and cast down and counted dead, the deepest point before the raising. The extended witnesses keep it whole: *they... stripped the coat of many colors which he had on* (Jasher 41:27); *they... cast him into a pit, and in the pit there was no water, but serpents and scorpions... and Yahuah (the Lord) hid the serpents and scorpions in the sides of the pit, and they did no harm to Joseph* (Jasher 41:28) — even in the place of death the kept one is preserved. And the restored reckoning keeps the father''s grief: *he mourned for Joseph one year, and did not cease, for he said "Let me go down to the grave mourning for my son"* (Jubilees 34:16). The beloved son, stripped and cast into the waterless pit and reckoned dead, is the shadow of the One who went down and was raised — the suffering before the glory.',
       sv.verse_id, ev.verse_id, 'extras', 20912
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=23
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=35
ON CONFLICT (slug) DO NOTHING;

-- THREAD 6 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-the-patriarchs-moved-with-envy-sold-joseph-into-egypt',
       E'The patriarchs, moved with envy, sold Joseph into Egypt — but Elohim was with him',
       E'The Spirit through Stephen reads the whole of Genesis 37 in a breath, and names it as the type the apostles preached: *And the patriarchs, moved with envy, sold Joseph into Egypt: but Elohim (God) was with him* (Acts 7:9). The envy is *his brethren envied him* (Genesis 37:11); the sale is *sold Joseph to the Ishmeelites... and they brought Joseph into Egypt* (Genesis 37:28). And then the turn the dreams foretold and the pit denied: *And delivered him out of all his afflictions, and gave him favour and wisdom in the sight of Pharaoh king of Egypt; and he made him governor over Egypt and all his house* (Acts 7:10). Here is the suffering-then-exalted shape entire — rejected by his own, sold, afflicted, yet Yahuah with him, delivered, and raised to rule and to save. Joseph himself names the pattern when at last he stands over his brethren: *ye thought evil against me; but Elohim (God) meant it unto good, to bring to pass, as it is this day, to save much people alive* (Genesis 50:20) — the very evil counsel of *let us slay him, and cast him into some pit... and we shall see what will become of his dreams* (Genesis 37:20) overruled to the saving of the many. This is the load-bearing reading: the rejected brother raised to deliver the very brethren who rejected him — the great type of the One sold, presumed dead, and raised to the right hand to save His people. (Canon witnesses throughout: this thread is free.)',
       sv.verse_id, ev.verse_id, 'free', 20915
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=20
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=28
ON CONFLICT (slug) DO NOTHING;

-- THREAD 7
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-the-stick-of-joseph-the-birthright-and-the-northern-house',
       E'The stick of Joseph, the birthright, and the northern house (the two-house weave)',
       E'The favour Jacob lays on the beloved son is more than a father''s fondness — it is the birthright passing to Joseph, and with it the headship of the northern house. *Yashar''el (Israel) loved Joseph more than all his children... and he made him a coat of many colours* (Genesis 37:3); the chronicler names what the coat signified: *his birthright was given unto the sons of Joseph the son of Yashar''el (Israel)* (1 Chronicles 5:1), *but the birthright was Joseph''s* (1 Chronicles 5:2) — even as *Yahudah (Judah) prevailed above his brethren, and of him came the chief ruler.* Here, at the head of the cycle, the two houses are already set: the birthright to Joseph (Ephraim, the north), the sceptre to Yahudah (Judah, the south). The prophet names Joseph the stick of the scattered house: *take... another stick, and write upon it, For Joseph, the stick of Ephraim, and for all the house of Yashar''el (Israel) his companions* (Ezekiel 37:16); and the gathering: *I will take the stick of Joseph, which is in the hand of Ephraim... and make them one stick, and they shall be one in mine hand* (Ezekiel 37:19). The rejected brother, sold by his own, becomes the saved-and-saving northern house, joined again to Yahudah (Judah). And at the last he stands among the sealed: *of the tribe of Joseph were sealed twelve thousand* (Revelation 7:8) — the eleven stars that bowed to him gathered with him at the end. The favour of the coat is the birthright of the house that must be made one. (Canon witnesses throughout: this thread is free.)',
       sv.verse_id, ev.verse_id, 'free', 20918
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=3
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=9
ON CONFLICT (slug) DO NOTHING;

-- THREAD 8
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-37-the-kid-of-the-goats-and-the-day-of-atonement',
       E'The kid of the goats and the Day of Atonement',
       E'To deceive the father, the brothers slay a goat and dip the beloved son''s coat in its blood: *they took Joseph''s coat, and killed a kid of the goats, and dipped the coat in the blood* (Genesis 37:31), *and said, This have we found: know now whether it be thy son''s coat or no* (Genesis 37:32). A goat dies to cover the brothers'' wrong against the beloved. The restored reckoning binds this very goat to the origin of the Day of Atonement: *it is ordained for the children of Yashar''el (Israel) that they should afflict themselves on the tenth of the seventh month... that they should make atonement for themselves thereon with a young goat... for their sins; for they had grieved the affection of their father regarding Joseph his son* (Jubilees 34:18). The goat whose blood deceived Jacob becomes the goat of the appointed day. And the Torah names the rite: *two kids of the goats for a sin offering* (Leviticus 16:5), on *the tenth day of this seventh month... a day of atonement... ye shall afflict your souls* (Leviticus 23:27). The goat slain to hide the sin against the beloved son is the shadow of the goat whose blood covers the people''s guilt — the brothers'' deceit answered, in the appointed time, by atonement.',
       sv.verse_id, ev.verse_id, 'extras', 20921
  FROM _s301_ge37_lookup sv, _s301_ge37_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=37 AND sv.verse_number=31
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=37 AND ev.verse_number=32
ON CONFLICT (slug) DO NOTHING;

